package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.net.Uri;import android.widget.*;import java.io.*;import java.util.*;

public final class StorageActivity extends WorkspaceActivity {
    String title(){return "Armazenamento";}
    static void open(Context c){c.startActivity(new Intent(c,StorageActivity.class));}
    void load(){PlusUi.longRun(this,()->{Map<String,Long> size=new LinkedHashMap<>();for(String folder:new String[]{"study-materials","voice-notes","narrations","backgrounds","book-covers","book-settings","ocr","workspace-recovery"})size.put(folder,StorageReview.bytes(StorageReview.files(new File(getFilesDir(),folder))));long cache=StorageReview.bytes(StorageReview.files(getCacheDir()));PlusUi.post(this,()->{content.removeAllViews();note(AppLanguage.text(this,"Espaço livre")+": "+android.text.format.Formatter.formatShortFileSize(this,getFilesDir().getUsableSpace()));row("book","Livros",format(size.get("study-materials")),()->startActivity(new Intent(this,MainActivity.class).putExtra("open_books",true)));row("audio","WAVs de narração",format(size.get("narrations"))+" · "+AppLanguage.text(this,"inclui apenas os WAVs privados recuperados"),this::narrations);row("mic","Notas de voz",format(size.get("voice-notes")),this::notes);row("audio","Fundos",format(size.get("backgrounds")),null);row("image","Capas",format(size.get("book-covers")),null);row("settings","Perfis e planos",format(size.get("book-settings")),null);row("scan","Dados de OCR",format(size.get("ocr")),this::models);row("clock","Recuperações anteriores",format(size.get("workspace-recovery")),this::recoveries);row("folder","Cache",format(cache),()->review(true));row("trash","Ficheiros sem ligação",AppLanguage.text(this,"Verificar antes de remover"),()->review(false));});});}
    String format(long bytes){return android.text.format.Formatter.formatShortFileSize(this,bytes);}
    void review(boolean cache){PlusUi.longRun(this,()->{List<File> candidates=cache?StorageReview.cache(this):StorageReview.unused(this);long bytes=StorageReview.bytes(candidates);PlusUi.post(this,()->{if(candidates.isEmpty()){PlusUi.toast(this,cache&&WorkLeases.readerOpen()?"Feche os leitores para limpar o cache.":"Não há ficheiros disponíveis para esta limpeza.");return;}UiPanel panel=new UiPanel(this,cache?"Rever cache":"Rever ficheiros sem ligação",candidates.size()+" · "+format(bytes),"trash");panel.action("document","Ver ficheiros",null,false,()->PagedPicker.show(this,"Ficheiros da limpeza",(query,offset,limit)->{List<File> matches=new ArrayList<>();for(File f:candidates)if(f.getName().toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))matches.add(f);List<PagedPicker.Entry> rows=new ArrayList<>();for(int i=offset;i<Math.min(matches.size(),offset+limit);i++){File f=matches.get(i);rows.add(new PagedPicker.Entry(f.getPath(),f.getName(),format(f.length())));}return new PagedPicker.Page(rows,matches.size());},entry->confirm(Collections.singletonList(new File(entry.id)),cache)));panel.danger("Remover ficheiros verificados",()->confirm(candidates,cache));panel.show();});});}
    void confirm(List<File> files,boolean cache){new UiDialog.Builder(this).setTitle("Remover os ficheiros seleccionados?").setMessage(files.size()+" · "+format(StorageReview.bytes(files))+"\n"+AppLanguage.text(this,"As referências e recuperações serão verificadas novamente antes de remover.")).setPositiveButton("Remover",(d,w)->PlusUi.longRun(this,()->{StorageReview.delete(this,files,cache);PlusUi.post(this,this::load);})).setNegativeButton("Cancelar",null).show();}
    void recoveries(){PlusUi.longRun(this,()->{File[] all=new File(getFilesDir(),"workspace-recovery").listFiles((d,n)->n.endsWith(".zip"));List<File> files=all==null?Collections.emptyList():Arrays.asList(all);PlusUi.post(this,()->PagedPicker.show(this,"Recuperações anteriores",(query,offset,limit)->{List<File> filtered=new ArrayList<>();for(File f:files)if(f.getName().contains(query))filtered.add(f);filtered.sort((a,b)->Long.compare(b.lastModified(),a.lastModified()));List<PagedPicker.Entry> rows=new ArrayList<>();for(int i=offset;i<Math.min(filtered.size(),offset+limit);i++){File f=filtered.get(i);rows.add(new PagedPicker.Entry(f.getPath(),new java.text.SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.getDefault()).format(new Date(f.lastModified())),format(f.length())));}return new PagedPicker.Page(rows,filtered.size());},entry->{File f=new File(entry.id);UiPanel p=new UiPanel(this,entry.label,entry.detail,"clock");p.action("restore","Rever e recuperar",null,false,()->BackupWork.local(this,f));p.danger("Eliminar este ponto de recuperação",()->new UiDialog.Builder(this).setTitle("Eliminar esta recuperação?").setMessage("Os dados actuais são conservados. Depois pode verificar novamente os ficheiros sem ligação.").setPositiveButton("Eliminar",(d,w)->PlusUi.longRun(this,()->{File root=new File(getFilesDir(),"workspace-recovery").getCanonicalFile();if(!DiskWalker.inside(root,f.getCanonicalFile())||TaskService.instance!=null&&TaskService.instance.running)throw new IOException("Aguarde as tarefas terminarem antes de eliminar uma recuperação.");if(!f.delete())throw new IOException("Não foi possível remover a recuperação.");PlusUi.post(this,this::load);})).setNegativeButton("Cancelar",null).show());p.show();}));});}
    void models(){UiPanel p=new UiPanel(this,"Dados de OCR",null,"scan");for(String language:new String[]{"por","eng"})if(OcrEngine.model(this,language).isFile())p.action("trash",language.equals("por")?"Português":"English",format(OcrEngine.model(this,language).length()),false,()->new UiDialog.Builder(this).setTitle("Eliminar dados de OCR?").setMessage("Pode voltar a descarregá-los. O texto já reconhecido é conservado.").setPositiveButton("Eliminar",(d,w)->{if(TaskService.instance!=null&&TaskService.instance.running){PlusUi.toast(this,"Aguarde as tarefas terminarem.");return;}for(android.app.Activity active:WorkLeases.snapshot())if(active instanceof ReaderActivity&&((ReaderActivity)active).extras!=null&&((ReaderActivity)active).extras.ocr!=null){PlusUi.toast(this,"Aguarde o OCR terminar.");return;}OcrEngine.model(this,language).delete();load();}).setNegativeButton("Cancelar",null).show());p.show();}
    void narrations(){PagedPicker.show(this,"WAVs de narração",(query,offset,limit)->{List<PagedPicker.Entry> rows=new ArrayList<>();long total;try(PlusStore db=new PlusStore(this)){String[] args={StudySchedule.like(query)};try(Cursor count=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM audio_tracks WHERE title LIKE ? ESCAPE '\\'",args)){count.moveToFirst();total=count.getLong(0);}try(Cursor c=db.getReadableDatabase().rawQuery("SELECT uri,title,duration FROM audio_tracks WHERE title LIKE ? ESCAPE '\\' ORDER BY created DESC LIMIT ? OFFSET ?",new String[]{args[0],""+limit,""+offset})){while(c.moveToNext())rows.add(new PagedPicker.Entry(c.getString(0),c.getString(1),ReaderActivity.clock((int)Math.min(Integer.MAX_VALUE,c.getLong(2)))));}}return new PagedPicker.Page(rows,total);},e->startActivity(new Intent(this,MediaActivity.class).setDataAndType(Uri.parse(e.id),"audio/wav").putExtra("name",e.label)));}
    void notes(){PagedPicker.show(this,"Notas de voz",(query,offset,limit)->{List<PagedPicker.Entry> rows=new ArrayList<>();long total;try(PlusStore db=new PlusStore(this)){String[] args={StudySchedule.like(query)};try(Cursor count=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM voice_notes WHERE title LIKE ? ESCAPE '\\'",args)){count.moveToFirst();total=count.getLong(0);}try(Cursor c=db.getReadableDatabase().rawQuery("SELECT id,title,segment FROM voice_notes WHERE title LIKE ? ESCAPE '\\' ORDER BY created DESC LIMIT ? OFFSET ?",new String[]{args[0],""+limit,""+offset})){while(c.moveToNext())rows.add(new PagedPicker.Entry(c.getString(0),c.getString(1),AppLanguage.text(this,"Parte")+" "+(c.getInt(2)+1)));}}return new PagedPicker.Page(rows,total);},e->startActivity(new Intent(this,MediaActivity.class).setDataAndType(PlusFileProvider.voice(this,Long.parseLong(e.id)),"audio/wav").putExtra("name",e.label)));}
}
